/* SEED — local-first tabletop. All game state is stored in this browser. */
(() => {
  'use strict';
  const STORE = 'seed-vtt-v1';
  const $ = (s, r = document) => r.querySelector(s);
  const $$ = (s, r = document) => [...r.querySelectorAll(s)];
  const uid = () => Math.random().toString(36).slice(2, 10);
  const escapeHtml = (s = '') => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const defaults = () => ({
    campaigns: [], characters: [], systems: [
      {id:'freeform',name:'Sistema Livre',version:'1.0',description:'Uma base flexível para jogar do seu jeito. Configure atributos e campos sem amarras.',attributes:['Vigor','Agilidade','Astúcia','Espírito'],skills:['Percepção','Sobrevivência','Influência'],dice:'d20',builtin:true},
      {id:'d20-fantasy',name:'Fantasia d20',version:'1.0',description:'Atributos clássicos, testes com d20 e aventuras de fantasia heroica.',attributes:['Força','Destreza','Constituição','Inteligência','Sabedoria','Carisma'],skills:['Atletismo','Arcanismo','Furtividade','Percepção'],dice:'d20',builtin:true},
      {id:'story',name:'Narrativo',version:'1.0',description:'Resolução flexível para histórias guiadas por personagens e consequências.',attributes:['Corpo','Mente','Presença'],skills:['Investigar','Convencer','Resistir'],dice:'d6',builtin:true}
    ], assets:[], rolls:[], activity:[], settings:{grid:64,gridType:'square',autosave:true}, activeCampaign:null
  });
  let state;
  try { state = JSON.parse(localStorage.getItem(STORE)) || defaults(); } catch { state = defaults(); }
  state = {...defaults(),...state};
  const save = () => { try { localStorage.setItem(STORE, JSON.stringify(state)); setSaved(); } catch(e) { toast('Armazenamento cheio. Remova alguns arquivos da biblioteca.'); } };
  let saveTimer;
  function setSaved(){ const dot=$('.save-dot');if(dot){dot.style.background='#91a571';dot.style.boxShadow='0 0 8px #91a5718c';}clearTimeout(saveTimer);saveTimer=setTimeout(()=>{if(dot){dot.style.background='#91a571';}},300); }
  function toast(message){const root=$('#toast-root');const n=document.createElement('div');n.className='toast';n.textContent=message;root.append(n);setTimeout(()=>n.remove(),3200);}
  function logActivity(text){state.activity.unshift({text,time:Date.now()});state.activity=state.activity.slice(0,30);save();}
  function campaignById(id){return state.campaigns.find(c=>c.id===id);}
  function activeCampaign(){return campaignById(state.activeCampaign)||state.campaigns[0]||null;}
  function getSystem(id){return state.systems.find(s=>s.id===id)||state.systems[0];}
  function titleFor(view){return ({dashboard:'Visão geral',campaigns:'Campanhas',characters:'Personagens',systems:'Sistemas de RPG',library:'Biblioteca',settings:'Configurações',tabletop:'Mesa virtual'})[view]||'Visão geral';}
  let currentView='dashboard';
  function navigate(view){currentView=view;$('#page-title').textContent=titleFor(view);$$('.nav-link[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#sidebar').classList.remove('open');render();}
  function render(){if(currentView==='tabletop')renderTabletop();else if(currentView==='dashboard')renderDashboard();else if(currentView==='campaigns')renderCampaigns();else if(currentView==='characters')renderCharacters();else if(currentView==='systems')renderSystems();else if(currentView==='library')renderLibrary();else if(currentView==='settings')renderSettings();$('#campaign-count').textContent=state.campaigns.length;}
  function art(rune='✧',label='CAMPANHA'){return `<div class="campaign-art"><span class="campaign-tag">${escapeHtml(label)}</span><span class="art-rune">${escapeHtml(rune)}</span></div>`;}
  function pageHead(title,description,button=''){return `<div class="page-head"><div><div class="eyebrow">✦ &nbsp; O grimório está aberto</div><h1>${title}</h1><p>${description}</p></div><div class="head-actions">${button}</div></div>`;}
  function campaignCard(c){const sys=getSystem(c.systemId);return `<article class="campaign-card" data-open-campaign="${c.id}">${art(c.rune||'✧',c.status||'EM ANDAMENTO')}<div class="campaign-info"><h3>${escapeHtml(c.name)}</h3><p>${escapeHtml(c.description||'Uma nova história aguarda ser escrita.')}</p><div class="campaign-meta"><span>${escapeHtml(sys.name)}</span><span class="players">♙ ${c.players?.length||1} aventureiro${(c.players?.length||1)===1?'':'s'}</span></div></div></article>`;}
  function renderDashboard(){const root=$('#view-root');const recent=state.campaigns.slice(0,3);const active=state.campaigns.filter(c=>c.status!=='Arquivada').length;const upcoming=state.campaigns.reduce((n,c)=>n+(c.sessions||[]).filter(s=>s.status==='Agendada').length,0);
    root.innerHTML=`<section class="hero"><div class="hero-content"><div class="hero-kicker"><i></i> A mesa está pronta</div><h1>Histórias à espera<br>de serem despertadas.</h1><p>Reúna seu grupo, abra o mapa e deixe que os dados decidam o destino.<br>Seu próximo mundo começa com uma única página.</p><div class="hero-buttons"><button class="primary-btn" data-action="create-campaign">＋ Nova campanha</button><button class="secondary-btn" data-action="create-character">♙ Criar personagem</button></div></div><div class="hero-art"><span>ᚱ</span></div></section>
    <div class="stats-grid"><div class="stat-card"><div class="stat-icon">♜</div><div><small>Campanhas ativas</small><strong>${active}</strong></div></div><div class="stat-card"><div class="stat-icon">♙</div><div><small>Personagens</small><strong>${state.characters.length}</strong></div></div><div class="stat-card"><div class="stat-icon">◷</div><div><small>Sessões agendadas</small><strong>${upcoming}</strong></div></div><div class="stat-card"><div class="stat-icon">⚄</div><div><small>Rolagens realizadas</small><strong>${state.rolls.length}</strong></div></div></div>
    <div class="section-heading"><h2>Campanhas recentes</h2><button data-nav="campaigns">Ver todas &nbsp;→</button></div>${recent.length?`<div class="campaign-grid">${recent.map(campaignCard).join('')}</div>`:`<div class="empty-state"><b>O primeiro capítulo ainda não foi escrito</b>Crie uma campanha para reunir personagens, mapas e sessões em um só lugar.<br><button class="primary-btn" data-action="create-campaign">＋ Criar campanha</button></div>`}
    <div class="content-columns"><section><div class="section-heading"><h2>Atividade recente</h2></div><div class="activity-list">${state.activity.length?state.activity.slice(0,5).map(a=>`<div class="activity-item"><div class="activity-glyph">✦</div><div>${escapeHtml(a.text)}<small>${new Date(a.time).toLocaleString('pt-BR',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})}</small></div></div>`).join(''):`<div class="activity-item"><div class="activity-glyph">⌁</div><div>Nenhum acontecimento registrado ainda.<small>Suas ações importantes aparecerão aqui.</small></div></div>`}</div></section><section><div class="section-heading"><h2>Próximas sessões</h2><button data-nav="campaigns">Campanhas →</button></div><div class="session-list">${sessionSummary()}</div></section></div>`;
  }
  function sessionSummary(){const sessions=state.campaigns.flatMap(c=>(c.sessions||[]).filter(s=>s.status==='Agendada').map(s=>({c,s}))).slice(0,4);return sessions.length?sessions.map(({c,s})=>`<div class="session-item"><div class="session-date"><b>${s.date?new Date(s.date+'T12:00:00').getDate():'—'}</b><small>${s.date?new Date(s.date+'T12:00:00').toLocaleString('pt-BR',{month:'short'}).toUpperCase():'DATA'}</small></div><div class="session-desc"><b>${escapeHtml(s.name)}</b><small>${escapeHtml(c.name)} · ${s.time||'Horário livre'}</small></div></div>`).join(''):'<div class="session-item"><div class="session-desc"><b>O destino está em aberto</b><small>Agende uma sessão dentro de uma campanha.</small></div></div>';}
  function renderCampaigns(){const root=$('#view-root');root.innerHTML=`${pageHead('Campanhas','Seus mundos, histórias e grupos em um único lugar.','<button class="primary-btn" data-action="create-campaign">＋ Nova campanha</button>')}<div class="toolbar-row"><div class="search-box"><input id="campaign-search" placeholder="Buscar campanha..." /></div><select class="select-control" id="campaign-filter"><option value="all">Todas as campanhas</option><option value="active">Em andamento</option><option value="archived">Arquivadas</option></select></div><div class="list-grid" id="campaign-list">${state.campaigns.length?state.campaigns.map(c=>`<article class="campaign-tile" data-open-campaign="${c.id}">${art(c.rune||'✧',c.status||'EM ANDAMENTO')}<div class="tile-body"><h3>${escapeHtml(c.name)}</h3><p>${escapeHtml(c.description||'Sem descrição. Abra para configurar a campanha.')}</p><div class="campaign-meta"><span>${escapeHtml(getSystem(c.systemId).name)}</span><span>${(c.sessions||[]).length} sessões</span></div><div class="tile-actions"><button class="secondary-btn" data-enter="${c.id}">Abrir mesa</button><button class="secondary-btn" data-edit-campaign="${c.id}">Editar</button><button class="secondary-btn" data-session="${c.id}">＋ Sessão</button></div></div></article>`).join(''):`<div class="empty-state" style="grid-column:1/-1"><b>Nenhuma campanha encontrada</b>Inicie uma campanha para preparar sua mesa.<br><button class="primary-btn" data-action="create-campaign">＋ Criar campanha</button></div>`}</div>`;}

