function renderCampaigns(){const root=$('#view-root');root.innerHTML=`${pageHead('Campanhas','Seus mundos, histórias e grupos em um único lugar.','<button class="primary-btn" data-action="create-campaign">＋ Nova campanha</button>')}<div class="toolbar-row"><div class="search-box"><input id="campaign-search" placeholder="Buscar campanha..." /></div><select class="select-control" id="campaign-filter"><option value="all">Todas as campanhas</option><option value="active">Em andamento</option><option value="archived">Arquivadas</option></select></div><div class="list-grid" id="campaign-list">${state.campaigns.length?state.campaigns.map(c=>`<article class="campaign-tile" data-open-campaign="${c.id}">${art(c.rune||'✧',c.status||'EM ANDAMENTO')}<div class="tile-body"><h3>${escapeHtml(c.name)}</h3><p>${escapeHtml(c.description||'Sem descrição. Abra para configurar a campanha.')}</p><div class="campaign-meta"><span>${escapeHtml(getSystem(c.systemId).name)}</span><span>${(c.sessions||[]).length} sessões</span></div><div class="tile-actions"><button class="secondary-btn" data-enter="${c.id}">Abrir mesa</button><button class="secondary-btn" data-edit-campaign="${c.id}">Editar</button><button class="secondary-btn" data-session="${c.id}">＋ Sessão</button></div></div></article>`).join(''):`<div class="empty-state" style="grid-column:1/-1"><b>Nenhuma campanha encontrada</b>Inicie uma campanha para preparar sua mesa.<br><button class="primary-btn" data-action="create-campaign">＋ Criar campanha</button></div>`}</div>`;}
function renderCharacters(){const root=$('#view-root');root.innerHTML=`${pageHead('Personagens','Heróis, antagonistas e destinos entrelaçados.','<button class="primary-btn" data-action="create-character">＋ Novo personagem</button>')}<div class="toolbar-row"><div class="search-box"><input id="character-search" placeholder="Buscar personagem..." /></div><select class="select-control" id="character-system-filter"><option value="all">Todos os sistemas</option>${state.systems.map(s=>`<option value="${s.id}">${escapeHtml(s.name)}</option>`).join('')}</select></div><div class="character-grid" id="character-list">${state.characters.length?state.characters.map(characterCard).join(''):'<div class="empty-state" style="grid-column:1/-1"><b>Uma lenda começa com um nome</b>Crie sua primeira ficha dinâmica e leve-a para qualquer mesa.<br><button class="primary-btn" data-action="create-character">＋ Criar personagem</button></div>'}</div>`;}
function characterCard(ch){const sys=getSystem(ch.systemId);const hp=Number(ch.hp)||0,max=Number(ch.maxHp)||1;return `<article class="character-card" data-character="${ch.id}"><div class="character-top"><div class="portrait">${ch.image?`<img src="${ch.image}" alt=""/>`:escapeHtml((ch.name||'?')[0].toUpperCase())}</div><div><h3>${escapeHtml(ch.name)}</h3><p class="muted">${escapeHtml(ch.role||'Aventureiro')} · ${escapeHtml(sys.name)}</p></div></div><div class="character-stats"><div class="mini-stat"><small>NÍVEL</small>${escapeHtml(ch.level||'—')}</div><div class="mini-stat"><small>PV</small>${hp} / ${max}<div class="resource-bar"><i style="width:${Math.max(0,Math.min(100,hp/max*100))}%"></i></div></div>${Object.entries(ch.attributes||{}).slice(0,1).map(([k,v])=>`<div class="mini-stat"><small>${escapeHtml(k.toUpperCase())}</small>${escapeHtml(v)}</div>`).join('')}</div><div class="character-footer"><span class="tag">${escapeHtml(ch.campaignName||'SEM CAMPANHA')}</span><button class="text-button" data-edit-character="${ch.id}">Editar ficha →</button></div></article>`;}
function renderSystems(){const root=$('#view-root');root.innerHTML=`${pageHead('Sistemas de RPG','Regras flexíveis. Sua mesa, suas escolhas.','<button class="primary-btn" data-action="create-system">＋ Novo sistema</button>')}<div class="system-grid">${state.systems.map((s,i)=>`<article class="system-card"><div class="system-symbol">${i===0?'ᚱ':i===1?'⚔':'✧'}</div><h3>${escapeHtml(s.name)}</h3><p>${escapeHtml(s.description)}</p><div class="rule-pills">${(s.attributes||[]).slice(0,4).map(a=>`<span>${escapeHtml(a)}</span>`).join('')}<span>${escapeHtml(s.dice||'d20')}</span></div><div class="system-foot"><span class="tag">${s.builtin?'BASE SEED':'PERSONALIZADO'} · v${escapeHtml(s.version||'1.0')}</span><button data-edit-system="${s.id}">Configurar →</button></div></article>`).join('')}</div><div class="settings-panel" style="margin-top:20px"><h3>Um motor de regras sem amarras</h3><p>Os sistemas definem atributos e dados para as fichas. A mesa não impõe classes, níveis ou cálculos: regras específicas podem ser anotadas livremente e as rolagens aceitam qualquer fórmula de dados.</p></div>`;}
function renderLibrary(){const root=$('#view-root');root.innerHTML=`${pageHead('Biblioteca','Mapas e imagens importados ficam disponíveis neste dispositivo.','<button class="primary-btn" data-action="upload-asset">＋ Importar arquivo</button>')}<div class="toolbar-row"><select class="select-control" id="asset-filter"><option value="all">Todas as categorias</option><option>Mapas</option><option>Tokens</option><option>Retratos</option><option>Outros</option></select><span class="tag">${state.assets.length} ARQUIVOS</span></div>${state.assets.length?`<div class="asset-grid">${state.assets.map(a=>`<article class="asset-card"><div class="asset-preview">${a.type?.startsWith('image/')?`<img src="${a.data}" alt="${escapeHtml(a.name)}">`:'▧'}</div><b>${escapeHtml(a.name)}</b><small>${escapeHtml(a.category)} · ${Math.round(a.size/1024)} KB</small><button class="text-button" data-delete-asset="${a.id}">Remover</button></article>`).join('')}</div>`:'<div class="empty-state"><b>Suas relíquias ficarão aqui</b>Importe mapas e imagens para usar na mesa. Os arquivos são guardados no armazenamento local do navegador.<br><button class="primary-btn" data-action="upload-asset">＋ Importar arquivo</button></div>'}<input id="asset-input" type="file" accept="image/*,.pdf,.txt" multiple hidden>`;}
function renderSettings(){const root=$('#view-root');root.innerHTML=`${pageHead('Configurações','Controle os dados locais e o comportamento da mesa.')}<section class="settings-panel"><h3>Dados e privacidade</h3><p>O SEED salva campanhas, personagens, rolagens e arquivos no armazenamento deste navegador. Nada é enviado a um servidor externo. Para jogar com outras pessoas remotamente, será necessário conectar um servidor multiplayer que ainda não está configurado.</p><div class="settings-actions"><button class="secondary-btn" data-action="export-data">⇩ Exportar cópia JSON</button><button class="secondary-btn" data-action="import-data">⇧ Restaurar cópia</button><button class="danger-btn" data-action="clear-data">Apagar dados locais</button></div><input id="import-data-input" type="file" accept="application/json" hidden></section><section class="settings-panel"><h3>Preferências de mesa</h3><p>Ajuste a grade padrão. O tipo e o tamanho também podem ser configurados por mapa.</p><div class="settings-actions"><label class="field">Tamanho da célula <select class="select-control" id="setting-grid">${[32,48,64,80,96].map(n=>`<option ${state.settings.grid===n?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">Grade padrão <select class="select-control" id="setting-grid-type"><option value="square" ${state.settings.gridType==='square'?'selected':''}>Quadrangular</option><option value="hex" ${state.settings.gridType==='hex'?'selected':''}>Hexagonal</option><option value="none">Sem grade</option></select></label></div></section><section class="settings-panel"><h3>Sobre o SEED</h3><p>Uma mesa virtual local-first e de código aberto em espírito: sem contas, APIs pagas ou dependências obrigatórias. Os dados permanecem neste navegador; faça exportações regulares como backup.</p></section>`;}
function openModal(title,body,actions='',wide=false){const root=$('#modal-root');root.innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'modal-wide':''}" role="dialog" aria-modal="true"><div class="modal-head"><h2>${title}</h2><button class="close-btn" data-close-modal aria-label="Fechar">×</button></div><div class="modal-body">${body}</div>${actions?`<div class="modal-actions">${actions}</div>`:''}</section></div>`;$('.modal-backdrop',root).addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal();});const focus=$('input,textarea,select',root);if(focus)focus.focus();}
function closeModal(){$('#modal-root').innerHTML='';}
const field=(label,name,value='',type='text',extra='')=>`<div class="field"><label>${label}</label><input name="${name}" type="${type}" value="${escapeHtml(value)}" ${extra}></div>`;
function createCampaign(existing){const c=existing||{};openModal(existing?'Editar campanha':'Nova campanha',`<form id="campaign-form"><div class="form-grid">${field('NOME DA CAMPANHA','name',c.name||'')}${field('AMBIENTAÇÃO / TOM','setting',c.setting||'Fantasia sombria')}<div class="field full"><label>DESCRIÇÃO</label><textarea name="description" placeholder="O que aguarda os aventureiros?">${escapeHtml(c.description||'')}</textarea></div><div class="field"><label>SISTEMA DE RPG</label><select name="systemId">${state.systems.map(s=>`<option value="${s.id}" ${(c.systemId||'freeform')===s.id?'selected':''}>${escapeHtml(s.name)}</option>`).join('')}</select></div><div class="field"><label>ESTADO</label><select name="status"><option ${!c.status||c.status==='EM ANDAMENTO'?'selected':''}>EM ANDAMENTO</option><option ${c.status==='Arquivada'?'selected':''}>Arquivada</option></select></div></div></form>`,`${existing?`<button class="danger-btn" data-delete-campaign="${c.id}" style="margin-right:auto">Excluir</button>`:''}<button class="secondary-btn" data-close-modal>Cancelar</button><button class="primary-btn" data-save-campaign="${c.id||''}">Salvar campanha</button>`);}
function createCharacter(existing){const ch=existing||{};const system=getSystem(ch.systemId||state.systems[0].id);const attr=Object.entries(ch.attributes||{});const attributes=system.attributes||[];openModal(existing?'Editar personagem':'Novo personagem',`<form id="character-form"><div class="form-grid">${field('NOME','name',ch.name||'')}${field('PAPEL / ARQUÉTIPO','role',ch.role||'Aventureiro')}${field('NÍVEL / MARCO','level',ch.level||'1')}${field('PONTOS DE VIDA ATUAIS','hp',ch.hp??10,'number')}${field('PONTOS DE VIDA MÁXIMOS','maxHp',ch.maxHp??10,'number')}<div class="field"><label>SISTEMA</label><select name="systemId" id="character-system">${state.systems.map(s=>`<option value="${s.id}" ${system.id===s.id?'selected':''}>${escapeHtml(s.name)}</option>`).join('')}</select></div><div class="field full"><label>CAMPANHA (OPCIONAL)</label><select name="campaignId"><option value="">Nenhuma</option>${state.campaigns.map(c=>`<option value="${c.id}" ${ch.campaignId===c.id?'selected':''}>${escapeHtml(c.name)}</option>`).join('')}</select></div><div class="field full"><label>ATRIBUTOS · valores livres</label><div class="attribute-editor">${attributes.map(a=>field(a,a,attr.find(x=>x[0]===a)?.[1]??'', 'text')).join('')}</div></div><div class="field full"><label>HISTÓRIA / NOTAS</label><textarea name="notes" placeholder="Motivações, laços, segredos...">${escapeHtml(ch.notes||'')}</textarea></div></div></form>`,`<button class="secondary-btn" data-close-modal>Cancelar</button><button class="primary-btn" data-save-character="${ch.id||''}">Salvar ficha</button>`);}
function createSystem(existing){const s=existing||{};openModal(existing?'Configurar sistema':'Novo sistema',`<form id="system-form"><div class="form-grid">${field('NOME','name',s.name||'')}${field('VERSÃO','version',s.version||'1.0')}<div class="field full"><label>DESCRIÇÃO</label><textarea name="description">${escapeHtml(s.description||'')}</textarea></div><div class="field full"><label>ATRIBUTOS (separados por vírgula)</label><input name="attributes" value="${escapeHtml((s.attributes||[]).join(', '))}" placeholder="Ex.: Vigor, Astúcia"></div><div class="field full"><label>PERÍCIAS / CAMPOS ADICIONAIS</label><input name="skills" value="${escapeHtml((s.skills||[]).join(', '))}" placeholder="Ex.: Sobrevivência, Ofício"></div><div class="field"><label>DADO PADRÃO INFORMATIVO</label><input name="dice" value="${escapeHtml(s.dice||'d20')}" placeholder="d20, d6... "></div></div></form><p style="font-size:9px;color:#8f8777">Os dados definidos aparecem como campos iniciais nas fichas. Fórmulas podem ser roladas diretamente na mesa.</p>`,`${existing&&!s.builtin?`<button class="danger-btn" data-delete-system="${s.id}" style="margin-right:auto">Excluir</button>`:''}<button class="secondary-btn" data-close-modal>Cancelar</button><button class="primary-btn" data-save-system="${s.id||''}">Salvar sistema</button>`);}

