function createToken(){const c=currentCampaign();if(!c){toast('Crie uma campanha antes de abrir a mesa.');navigate('campaigns');return;}openModal('Adicionar token',`<form id="token-form"><div class="form-grid">${field('NOME','name','Novo aventureiro')}<div class="field"><label>PERSONAGEM VINCULADO</label><select name="characterId"><option value="">Token livre</option>${state.characters.map(ch=>`<option value="${ch.id}">${escapeHtml(ch.name)}</option>`).join('')}</select></div><div class="field"><label>TIPO</label><select name="kind"><option value="hero">Aliado</option><option value="enemy">Adversário</option><option value="neutral">Neutro</option></select></div><div class="field"><label>INICIATIVA</label><input name="initiative" type="number" value="10"></div></div></form>`,`<button class="secondary-btn" data-close-modal>Cancelar</button><button class="primary-btn" data-save-token>Adicionar token</button>`);}
function parseRoll(expression){const m=String(expression).trim().toLowerCase().match(/^(\d*)d(\d+)(?:\s*([+-])\s*(\d+))?$/);if(!m)throw new Error('Use uma fórmula como d20, 2d6+3 ou 1d100.');const count=Number(m[1]||1),sides=Number(m[2]),mod=Number(m[4]||0)*(m[3]==='-'?-1:1);if(count<1||count>100||sides<2||sides>10000||mod>100000||mod< -100000)throw new Error('Limites: até 100 dados, d2–d10000 e modificador de 100000.');const dice=Array.from({length:count},()=>1+Math.floor(Math.random()*sides));return{expression:String(expression).trim(),dice,mod,total:dice.reduce((a,b)=>a+b,0)+mod};}
function recordRoll(expression,author='Mestre'){try{const r=parseRoll(expression);r.id=uid();r.time=Date.now();r.author=author;state.rolls.unshift(r);state.rolls=state.rolls.slice(0,100);const c=currentCampaign();if(c){c.chat=c.chat||[];c.chat.push({id:uid(),author,text:`rolou ${r.expression}: ${r.total}`,roll:true,time:r.time});c.chat=c.chat.slice(-100);}save();if(currentView==='tabletop')renderTabletop();else renderDashboard();return r;}catch(e){toast(e.message);return null;}}
function diceModal(){const recent=state.rolls.slice(0,8);openModal('Rolar dados',`<form id="roll-form"><div class="field"><label>FÓRMULA</label><input name="formula" value="d20" placeholder="d20, 2d6+3" required></div></form><div class="roll-history">${recent.map(r=>`<div class="roll-item"><span>${escapeHtml(r.expression)} · ${new Date(r.time).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</span><b>${r.total}</b></div>`).join('')||'<p class="muted">Suas rolagens aparecerão aqui.</p>'}</div>`,`<button class="secondary-btn" data-close-modal>Fechar</button><button class="primary-btn" data-roll-modal>Rolar</button>`);}
function renderTabletop(){const root=$('#view-root'),c=currentCampaign();if(!c){root.innerHTML=`<div class="empty-state"><b>A mesa precisa de uma campanha</b>Crie ou selecione uma campanha para abrir o mapa, tokens e combate.<br><button class="primary-btn" data-action="create-campaign">＋ Nova campanha</button></div>`;return;}const t=tabletopFor(c),asset=state.assets.find(a=>a.id===t.mapAssetId);root.innerHTML=`<section class="tabletop-view"><div class="session-bar"><div class="session-title">${escapeHtml(c.name)} <small>· ${escapeHtml(getSystem(c.systemId).name)}</small></div><div class="session-tools"><button data-action="new-session" class="hide-mobile">◷ Sessão</button><button data-action="map-image" class="hide-mobile">▧ Mapa</button><button data-action="toggle-grid">Grade: ${t.gridType==='none'?'off':t.grid+'px'}</button><button data-action="add-token">＋ Token</button></div></div><div class="tabletop-layout"><div class="map-tools"><button class="map-tool active" data-tool="select" title="Selecionar / mover">↖</button><button class="map-tool" data-tool="pan" title="Mover mapa">✥</button><button class="map-tool" data-tool="token" title="Adicionar token">♙</button><button class="map-tool" data-tool="measure" title="Medir distância">↔</button><div class="tool-divider"></div><button class="map-tool" data-action="map-image" title="Escolher mapa">▧</button><button class="map-tool" data-action="toggle-grid" title="Alternar grade">▦</button><button class="map-tool" data-action="center-map" title="Centralizar">⌖</button></div><div class="map-workspace"><canvas id="map-canvas" class="map-canvas" aria-label="Mapa da mesa"></canvas><div class="map-hud"><span class="hud-chip">${asset?escapeHtml(asset.name):'MAPA SEM IMAGEM'}</span><span class="hud-chip">${t.gridType==='none'?'SEM GRADE':t.gridType==='hex'?'GRADE HEXAGONAL':`GRADE ${t.grid}px`}</span></div><div class="map-zoom"><button data-zoom="out">−</button><button data-zoom="in">＋</button><button data-action="center-map">⌖</button></div></div><aside class="map-right"><div class="right-tabs"><button class="active" data-tab="combat">Combate</button><button data-tab="tokens">Tokens</button><button data-tab="notes">Notas</button></div><div class="right-content" id="tabletop-panel"></div></aside></div><div class="bottom-dock"><section class="chat-panel"><div class="dock-heading">CHAT DA MESA <small>Somente neste dispositivo</small></div><div class="chat-log" id="chat-log">${(c.chat||[]).slice(-20).map(m=>`<p class="chat-line"><b>${escapeHtml(m.author||'Mestre')}</b><span class="${m.roll?'roll-text':''}">${escapeHtml(m.text)}</span></p>`).join('')||'<p class="chat-line">A conversa da mesa começa aqui.</p>'}</div><form class="chat-form" id="chat-form"><input name="message" placeholder="Mensagem ou /roll 2d6+2" autocomplete="off"><button>Enviar</button></form></section><section class="dice-panel"><div class="dock-heading">✦ &nbsp; ROLAGEM RÁPIDA</div><div class="quick-rolls">${[4,6,8,10,12,20].map(n=>`<button data-quick-roll="d${n}">d${n}</button>`).join('')}</div><form class="inline-roll" id="inline-roll"><input name="formula" value="d20" aria-label="Fórmula de dados"><button>Rolar</button></form><div class="dice-last">${state.rolls[0]?`${escapeHtml(state.rolls[0].expression)} = ${state.rolls[0].total}`:'Nenhuma rolagem ainda'}</div></section></div></section>`;renderTabletopPanel();initCanvas();}

