const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async()=>{
 const browser=await chromium.launch({headless:true,executablePath:'/usr/bin/chromium',args:['--no-sandbox','--disable-dev-shm-usage']});
 const page=await browser.newPage({viewport:{width:1440,height:1000},acceptDownloads:true});
 const errors=[],bad=[]; page.on('pageerror',e=>errors.push(e.message)); page.on('console',m=>{if(m.type()==='error')errors.push(m.text())}); page.on('response',r=>{if(r.status()>=400)bad.push([r.status(),r.url()])});
 const results={};
 await page.goto('http://localhost:3002'); await page.evaluate(()=>localStorage.clear()); await page.reload();
 const click=async s=>page.locator(s).first().click();
 await click('[data-action="create-campaign"]'); await page.locator('#campaign-form [name=name]').fill('Cripta da Lua'); await page.locator('#campaign-form [name=description]').fill('Uma campanha de teste'); await click('[data-save-campaign]'); results.campaign=await page.locator('.campaign-tile').count();
 await click('[data-view="characters"]'); await click('[data-action="create-character"]'); await page.locator('#character-form [name=name]').fill('Mira'); await click('[data-save-character]'); results.character=await page.locator('.character-card').count();
 await click('[data-view="systems"]'); await click('[data-action="create-system"]'); await page.locator('#system-form [name=name]').fill('Brumas'); await page.locator('#system-form [name=attributes]').fill('Sombra, Fôlego'); await click('[data-save-system]'); results.system=await page.locator('.system-card').count();
 await click('[data-view="campaigns"]'); await click('[data-session]'); await page.locator('#session-form [name=name]').fill('Primeira vigília'); await page.locator('#session-form [name=date]').fill('2026-11-18'); await click('[data-save-session]'); results.session=await page.locator('.campaign-tile').count();
 await click('[data-enter]'); results.tabletop=await page.locator('#map-canvas').count();
 await click('[data-action="add-token"]'); await page.locator('#token-form [name=name]').fill('Sentinela'); await page.locator('#token-form [name=kind]').selectOption('enemy'); await click('[data-save-token]'); results.token=await page.locator('#tabletop-panel').innerText();
 await click('[data-action="start-combat"]'); results.combat=(await page.locator('#tabletop-panel').innerText()).includes('TURNO ATUAL'); await click('[data-action="next-turn"]');
 await page.locator('#inline-roll [name=formula]').fill('2d6+3'); await page.locator('#inline-roll button').click(); results.roll=await page.locator('.dice-last').innerText();
 await page.locator('#chat-form [name=message]').fill('Boa sorte!'); await page.locator('#chat-form button').click(); results.chat=(await page.locator('#chat-log').innerText()).includes('Boa sorte!');
 await click('[data-view="library"]'); await click('[data-action="upload-asset"]'); await click('[data-start-upload]'); const chooser=await page.waitForEvent('filechooser'); await chooser.setFiles({name:'mapa.png',mimeType:'image/png',buffer:Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+/lWQAAAAASUVORK5CYII=','base64')}); await page.waitForTimeout(300); results.asset=await page.locator('.asset-card').count();
 await click('[data-view="settings"]'); const [download]=await Promise.all([page.waitForEvent('download'),click('[data-action="export-data]')]); results.backup=download.suggestedFilename();
 await page.reload(); results.persisted=await page.evaluate(()=>{let s=JSON.parse(localStorage.getItem('seed-vtt-v1'));return [s.campaigns.length,s.characters.length,s.systems.length,s.assets.length,s.rolls.length,s.campaigns[0].chat.length]});
 await page.setViewportSize({width:390,height:844}); await click('[data-view="tabletop"]'); results.mobile=await page.evaluate(()=>({inner:innerWidth,scroll:document.documentElement.scrollWidth,canvas:document.querySelector('#map-canvas')?.getBoundingClientRect().width,menu:getComputedStyle(document.querySelector('#mobile-menu')).display}));
 results.errors=errors; results.bad=bad;
 await browser.close(); console.log(JSON.stringify(results,null,2));
})().catch(e=>{console.error(e);process.exit(1)});

